def count_business_days(start_date: str, end_date: str) -> int:
    """
    start_date: ISO-86061 date string (e.g. '2024-02-29') marking the inclusive start of the period
    end_date: ISO-8601 date string (e.g. '2024-02-29') marking the inclusive end of the period
    returns: Number of calendar days from start_date to end_date inclusive, counting only weekdays (Monday through Friday). Returns 0 if start_date is after end_date.
    """
    from datetime import date

    try:
        s = date.fromisoformat(start_date)
        e = date.fromisoformat(end_date)
    except Exception:
        return 0

    if s > e:
        return 0

    # helper: number of weekdays up to and including day d
    def weekdays_up_to(d: date) -> int:
        # days since Monday (0) for the given date (0 = Monday, ..., 6 = Sunday)
        offset = (d.weekday() - 0) % 7  # always 0..6
        # full weeks * 5 weekdays + weekday offset
        return d.toordinal() // 7 * 5 + min(offset, 5)

    return weekdays_up_to(e) - weekdays_up_to(s) + (1 if s.weekday() < 5 else 0)

